// embeddedLibraryDocs holds, per js-lib recipe ID, the Svalbard-written
// quickstart of each library (<LibraryDocName>, body only: apply writes its
// frontmatter from the recipe) and the library's reference file
// (<LibraryReferenceName>, generated by build-tools/cmd/js-docs).
//
//go:embed libdocs
var embeddedLibraryDocs embed.FS

// libraryDocTree is the tree writeLibraryDocs reads; tests replace it.
var libraryDocTree = func() fs.FS {
	sub, err := fs.Sub(embeddedLibraryDocs, "libdocs")
	if err != nil {
		panic(err)
	}
	return sub
}

// EmbeddedLibraryDocs returns the embedded quickstarts and reference files,
// rooted above the recipe directories.
func EmbeddedLibraryDocs() fs.FS { return libraryDocTree() }

// libraryDocsDir is where a js-lib recipe's quickstarts go, beside its
// archive: lib/js/<id>/docs/, the folder the drive's index reads.
func libraryDocsDir(id string) string {
	return path.Join(TypeDirs[catalog.LibraryType], id, "docs")
}

// writeLibraryDocs writes into lib/js/<id>/docs/ of each realized js-lib
// recipe one quickstart per library, with frontmatter from the recipe
// (package, version, licence, portability, entry, requires) and the
// embedded text, and the library's reference file where there is one. A
// library without an embedded quickstart (a user recipe's) gets its README
// from the recipe's archive instead. A file is written only when its bytes
// differ, so the index does not read unchanged docs again. Files Svalbard
// did not write there are removed, and so are the folders of js-lib
// recipes that are no longer realized; lib/js/ itself stays, since a
// missing index root is not a prune.
func writeLibraryDocs(root string, entries []manifest.RealizedEntry, recipes map[string]catalog.Item, docs fs.FS) error {
	realized := map[string]bool{}
	for _, entry := range entries {
		if entry.Type != catalog.LibraryType {
			continue
		}
		realized[entry.ID] = true
		recipe, ok := recipes[entry.ID]
		if !ok {
			continue // the catalog no longer has it: keep what is there
		}
		want, err := libraryDocFiles(root, entry, recipe, docs)
		if err != nil {
			return fmt.Errorf("library docs of %s: %w", entry.ID, err)
		}
		if err := syncDocsFolder(filepath.Join(root, filepath.FromSlash(libraryDocsDir(entry.ID))), want); err != nil {
			return fmt.Errorf("library docs of %s: %w", entry.ID, err)
		}
	}
	base := filepath.Join(root, filepath.FromSlash(TypeDirs[catalog.LibraryType]))
	children, err := os.ReadDir(base)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for _, child := range children {
		if child.IsDir() && !realized[child.Name()] && !strings.HasPrefix(child.Name(), ".") {
			if err := os.RemoveAll(filepath.Join(base, child.Name())); err != nil {
				return err
			}
		}
	}
	return nil
}

// libraryDocFiles returns the docs folder's files by name.
func libraryDocFiles(root string, entry manifest.RealizedEntry, recipe catalog.Item, docs fs.FS) (map[string][]byte, error) {
	libraries := recipe.Libraries
	var archive *zip.ReadCloser
	openArchive := func() *zip.ReadCloser {
		if archive == nil {
			archive, _ = zip.OpenReader(filepath.Join(root, entry.RelativePath))
		}
		return archive
	}
	defer func() {
		if archive != nil {
			archive.Close()
		}
	}()
	if len(libraries) == 0 {
		// A recipe without libraries: (a user's) documents each top-level
		// package it installs.
		for _, source := range recipe.Bundle {
			if pkg := catalog.TopLevelPackage(source); pkg != "" {
				lib := catalog.Library{Package: pkg, Entry: pkg}
				if r := openArchive(); r != nil {
					lib.Version, lib.License, lib.Description = packageInfo(r, pkg)
				}
				libraries = append(libraries, lib)
			}
		}
	}
	want := map[string][]byte{}
	for _, lib := range libraries {
		name := catalog.LibraryDocName(lib.Package)
		body, err := fs.ReadFile(docs, path.Join(entry.ID, name))
		if err != nil {
			body = readmeBody(openArchive(), lib)
		}
		want[name] = append(libraryFrontmatter(lib, entry.ID), body...)
		reference := catalog.LibraryReferenceName(lib.Package)
		if data, err := fs.ReadFile(docs, path.Join(entry.ID, reference)); err == nil {
			want[reference] = data
		}
	}
	return want, nil
}

// libraryFrontmatter is what the drive's skill_search reads from a
// quickstart on the drive.
func libraryFrontmatter(lib catalog.Library, recipeID string) []byte {
	var b strings.Builder
	b.WriteString("---\n")
	field := func(key, value string) {
		if value == "" {
			return
		}
		quote := `"`
		if strings.Contains(value, `"`) {
			quote = "'"
		}
		fmt.Fprintf(&b, "%s: %s%s%s\n", key, quote, strings.Join(strings.Fields(value), " "), quote)
	}
	field("name", lib.Package)
	field("description", lib.Description)
	field("package", lib.Package)
	field("version", lib.Version)
	field("license", lib.License)
	field("portability", lib.Portability)
	field("entry", lib.Entry)
	fmt.Fprintf(&b, "requires: [%s]\n", recipeID)
	b.WriteString("---\n")
	return []byte(b.String())
}

// readmeBody is the quickstart of a library Svalbard wrote none for: its
// README from the archive, or a line naming it.
func readmeBody(archive *zip.ReadCloser, lib catalog.Library) []byte {
	if archive != nil {
		for _, name := range []string{"README.md", "readme.md", "Readme.md", "README.markdown", "README"} {
			f, err := archive.Open("node_modules/" + lib.Package + "/" + name)
			if err != nil {
				continue
			}
			data, err := io.ReadAll(f)
			f.Close()
			if err == nil {
				return append([]byte("No Svalbard quickstart; this is the package's README.\n\n"), data...)
			}
		}
	}
	return []byte(fmt.Sprintf("# %s\n\nNo quickstart or README. Import it in a module script as %q and pack the page with svalbard-drive html pack.\n", lib.Package, lib.Entry))
}

// packageInfo reads version, licence and description from a package.json in
// the archive.
func packageInfo(archive *zip.ReadCloser, pkg string) (version, license, description string) {
	f, err := archive.Open("node_modules/" + pkg + "/package.json")
	if err != nil {
		return "", "", ""
	}
	defer f.Close()
	var meta struct {
		Version     string `json:"version"`
		License     any    `json:"license"`
		Description string `json:"description"`
	}
	if json.NewDecoder(f).Decode(&meta) != nil {
		return "", "", ""
	}
	if s, ok := meta.License.(string); ok {
		license = s
	}
	return meta.Version, license, meta.Description
}

// syncDocsFolder makes dir hold exactly want, writing only files whose bytes
// differ. Hidden files (the system's) are left alone.
func syncDocsFolder(dir string, want map[string][]byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	children, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, child := range children {
		if strings.HasPrefix(child.Name(), ".svalbard-tmp-") {
			os.Remove(filepath.Join(dir, child.Name()))
			continue
		}
		if _, ok := want[child.Name()]; ok || strings.HasPrefix(child.Name(), ".") {
			continue
		}
		if err := os.RemoveAll(filepath.Join(dir, child.Name())); err != nil {
			return err
		}
	}
	for name, data := range want {
		target := filepath.Join(dir, name)
		if current, err := os.ReadFile(target); err == nil && bytes.Equal(current, data) {
			continue
		}
		if err := writeFileAtomic(target, data, 0o644); err != nil {
			return err
		}
	}
	return nil
}
